export function Organisation({
  orgName = "{{orgName}}",
  plan = "{{plan}}",
  memberCount = {{memberCount}},
  accent = "{{accent}}",
}) {
  const features = {
    free: "Included: shared workspace, 3 projects",
    pro: "Included: shared workspace, unlimited projects, roles",
    enterprise: "Included: everything in Pro, SSO, audit log",
  }[plan];
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
        <span style={{ width: 40, height: 40, borderRadius: 10, background: accent, flexShrink: 0, display: "block" }} />
        <div><strong style={{ display: "block" }}>{orgName}</strong><small style={{ color: "#24143099", fontSize: 11 }}>{memberCount} members</small></div>
      </div>
      <p style={{ margin: 0, fontSize: 11, background: "#24143010", padding: 10, borderRadius: 8 }}>{features}</p>
    </div>
  );
}
